const TOPICS = [{"t": "FAQ","p": "Page","u": "faq.html","k": "faq help troubleshooting problems questions"},{"t": "Help","p": "Page","u": "topics.html","k": "all topics docs documentation"},{"t": "Installing","p": "FAQ","u": "faq.html#faq-install","k": ""},{"t": "Playing","p": "FAQ","u": "faq.html#faq-playback","k": ""},{"t": "Subtitles","p": "FAQ","u": "faq.html#faq-subtitles","k": ""},{"t": "Debrid","p": "FAQ","u": "faq.html#faq-debrid","k": ""},{"t": "iPhone remote","p": "FAQ","u": "faq.html#faq-remote","k": ""},{"t": "Watch Party","p": "FAQ","u": "faq.html#faq-party","k": ""},{"t": "Downloads","p": "FAQ","u": "faq.html#faq-downloads","k": ""},{"t": "Account and everything else","p": "FAQ","u": "faq.html#faq-accounts","k": ""},{"t": "My Mac won't open Bluebox","p": "FAQ","u": "faq.html#cant-open-mac","k": "gatekeeper apple could not verify open anyway warning","q": 1},{"t": "It says Bluebox “is damaged and can't be opened”","p": "FAQ","u": "faq.html#damaged","k": "damaged broken","q": 1},{"t": "My Mac keeps asking for my password","p": "FAQ","u": "faq.html#keychain-prompts","k": "keychain password always allow","q": 1},{"t": "The update won't install on my Mac","p": "FAQ","u": "faq.html#mac-update-fails","k": "update fails app management","q": 1},{"t": "Bluebox stopped opening on my iPhone","p": "FAQ","u": "faq.html#ios-stopped-opening","k": "expired 7 days refresh free apple id","q": 1},{"t": "Nothing happens when I tap Open in AltStore","p": "FAQ","u": "faq.html#add-page-nothing","k": "add page sidestore feather","q": 1},{"t": "Can I use Bluebox on an Intel Mac, Apple TV, Android or Windows?","p": "FAQ","u": "faq.html#platforms","k": "intel apple tv android windows","q": 1},{"t": "Nothing plays, or it keeps loading","p": "FAQ","u": "faq.html#stream-wont-start","k": "won't start loading stuck spinning","q": 1},{"t": "It keeps stopping to buffer","p": "FAQ","u": "faq.html#buffering","k": "buffering pauses slow","q": 1},{"t": "Will my file play?","p": "FAQ","u": "faq.html#formats","k": "mkv mp4 avi format","q": 1},{"t": "I can't AirPlay to my TV","p": "FAQ","u": "faq.html#airplay-greyed","k": "airplay greyed tv mkv","q": 1},{"t": "The picture freezes but the sound keeps going","p": "FAQ","u": "faq.html#frozen-picture","k": "frozen freeze picture stuck","q": 1},{"t": "Subtitles don't match what people say","p": "FAQ","u": "faq.html#subtitles-sync","k": "out of sync early late delay timing","q": 1},{"t": "I can't find subtitles in my language","p": "FAQ","u": "faq.html#no-subtitles","k": "missing language opensubtitles search online","q": 1},{"t": "Some subtitles won't change size or move","p": "FAQ","u": "faq.html#subtitles-style","k": "ass style karaoke blu-ray picture subtitles","q": 1},{"t": "My debrid service shows an error","p": "FAQ","u": "faq.html#debrid-errors","k": "key not accepted plan expired limit reached not ready","q": 1},{"t": "Nothing shows as Cached","p": "FAQ","u": "faq.html#debrid-not-cached","k": "cached check what's cached","q": 1},{"t": "My iPhone can't find my Mac","p": "FAQ","u": "faq.html#remote-not-connecting","k": "remote not connecting no mac to control","q": 1},{"t": "My friends can't join my party","p": "FAQ","u": "faq.html#party-guests","k": "guests anonymous sign-ins join","q": 1},{"t": "The invite link says it's incomplete","p": "FAQ","u": "faq.html#party-incomplete","k": "incomplete invite link cut off","q": 1},{"t": "Downloads stop when I leave Bluebox on my iPhone","p": "FAQ","u": "faq.html#background-downloads","k": "background torrent stops battery","q": 1},{"t": "My downloads say Waiting","p": "FAQ","u": "faq.html#downloads-waiting","k": "waiting queued wifi window","q": 1},{"t": "There's no way to download this one","p": "FAQ","u": "faq.html#cant-download","k": "can't download hls stream","q": 1},{"t": "Do I need an account?","p": "FAQ","u": "faq.html#need-supabase","k": "account supabase required","q": 1},{"t": "I forgot my password","p": "FAQ","u": "faq.html#forgot-password","k": "password reset forgot","q": 1},{"t": "Sync stopped working","p": "FAQ","u": "faq.html#project-paused","k": "paused sync stopped restore","q": 1},{"t": "I forgot a profile's PIN","p": "FAQ","u": "faq.html#forgot-pin-faq","k": "pin forgot reset","q": 1},{"t": "How do I report a bug?","p": "FAQ","u": "faq.html#report-bug","k": "bug issue logs report","q": 1},{"t": "How do I start fresh?","p": "FAQ","u": "faq.html#reset","k": "reset erase start over","q": 1},{"t": "Does Bluebox come with films and shows?","p": "FAQ","u": "faq.html#legal","k": "legal content piracy","q": 1},{"t": "Can I use Bluebox in my language?","p": "FAQ","u": "faq.html#language","k": "language translation","q": 1},{"t": "Bluebox","p": "Page","u": "./","k": "home"},{"t": "Install","p": "Page","u": "install.html","k": "getting started setup download first run"},{"t": "What you need","p": "Install","u": "install.html#requirements","k": ""},{"t": "Mac","p": "Install","u": "install.html#mac","k": "dmg gatekeeper open anyway notarized macos"},{"t": "The first time: “Apple could not verify Bluebox”","p": "Install","u": "install.html#gatekeeper","k": "cannot be opened apple could not verify open anyway privacy security"},{"t": "If your Mac asks for your password","p": "Install","u": "install.html#keychain","k": "password keychain always allow"},{"t": "iPhone and iPad","p": "Install","u": "install.html#iphone","k": "ios ipad sideload altstore"},{"t": "With AltStore, SideStore or Feather","p": "Install","u": "install.html#altstore","k": ""},{"t": "With FlareStore, ESign or another app","p": "Install","u": "install.html#flarestore","k": ""},{"t": "Just the file","p": "Install","u": "install.html#ipa","k": ""},{"t": "First things to set up","p": "Install","u": "install.html#first-run","k": "tmdb token omdb setup"},{"t": "Finding your way around","p": "Install","u": "install.html#finding-your-way","k": ""},{"t": "Updates","p": "Install","u": "install.html#updates","k": "update new version"},{"t": "Uninstall","p": "Install","u": "install.html#uninstall","k": "remove delete erase"},{"t": "Check the download is genuine","p": "Install · technical details","u": "install.html#verify-download","k": "technical Bluebox is signed with its own certificate, not a paid Apple Developer ID, so Apple hasn't notarized it. Every Mac release is signed with the self-signed Bluebox Open Source certificate, SHA-1 8DA48EE5DF68786C0B40A9D6689453892A1F75D0. To check it, in Terminal: codesign -v --strict --deep -R='identifier \"app.bluebox.Bluebox.mac\" and certificate leaf = H\"8da48ee5df68786c0b40a9d6689453892a1f75d0\"' /Applications/Bluebox.app No output means the signature matches. Anything else means it isn't the app released on GitHub: delete it and download it again from the Releases page."},{"t": "Opening a sideloading app directly","p": "Install · technical details","u": "install.html#tech-opening-a-sideloading-app-directly","k": "technical add.html?to=altstore opens AltStore straight away; ?to=sidestore and ?to=feather work too."},{"t": "How the Mac updater checks a download","p": "Install · technical details","u": "install.html#tech-how-the-mac-updater-checks-a-download","k": "technical Bluebox checks GitHub's latest release once a day. The updater installs only a Bluebox signed with the release certificate, checks the download against GitHub's checksum, and puts the old version back if the new one fails its check. Releases are all signed with the same certificate, so a Keychain “Always Allow” lasts across updates."},{"t": "Build from source","p": "Install · technical details","u": "install.html#build","k": "technical You need Xcode and XcodeGen. The code is in the Bluebox folder of the repository. brew install xcodegen cd Bluebox && xcodegen generate && open Bluebox.xcodeproj Pick the Bluebox-iOS or Bluebox-macOS scheme and set your own team under Signing & Capabilities (or change DEVELOPMENT_TEAM in project.yml). Nothing needs a key to build. The torrent engine ships prebuilt; scripts/build-libtorrent.sh rebuilds it from source (brew install cmake ninja boost first). Run the tests with cd Bluebox/Packages/BlueboxKit && swift test."},{"t": "The player","p": "Page","u": "player.html","k": "player playback video"},{"t": "Controls","p": "The player","u": "player.html#controls","k": "seek speed gestures up next handoff"},{"t": "If it won't play","p": "The player","u": "player.html#wont-play","k": "won't start loading buffering stuck"},{"t": "Skip intro, recap and credits","p": "The player","u": "player.html#skipping","k": "skip intro recap credits"},{"t": "Subtitles","p": "The player","u": "player.html#subtitles","k": "captions srt language opensubtitles"},{"t": "Subtitle style","p": "The player","u": "player.html#subtitle-style","k": "font size colour position preset"},{"t": "Subtitles early or late","p": "The player","u": "player.html#subtitle-timing","k": "sync delay early late drift"},{"t": "Audio","p": "The player","u": "player.html#audio","k": "audio track language equaliser dialogue boost night mode"},{"t": "Picture and tools","p": "The player","u": "player.html#picture","k": "aspect crop zoom brightness sleep timer save frame"},{"t": "AirPlay and picture in picture","p": "The player","u": "player.html#airplay","k": "airplay tv picture in picture pip greyed"},{"t": "Will my file play?","p": "The player","u": "player.html#formats","k": "mkv mp4 avi webm vlc avplayer codec"},{"t": "Open in another player","p": "The player","u": "player.html#external-players","k": "infuse vlc iina mpv nplayer vidhub open in"},{"t": "Keyboard shortcuts (Mac)","p": "The player","u": "player.html#shortcuts","k": "keyboard shortcuts keys"},{"t": "More controls","p": "The player · technical details","u": "player.html#tech-more-controls","k": "technical Skip lengths: Settings › Playback › Skip Back / Skip Forward. Swipe Gestures can be turned off. Timeline: chapter marks from the file and, for torrents, how much is downloaded. Hovering or scrubbing shows preview pictures. Speed from 0.25× to 4×, with voices kept at their pitch. Speed carries over between episodes. Jump to Time goes to a time you type. The next episode is found in the background, so it starts quickly. Handoff offers what's playing to your other Apple devices."},{"t": "Where skip times come from","p": "The player · technical details","u": "player.html#tech-where-skip-times-come-from","k": "technical The buttons show for 8 seconds, then whenever the controls are up. Times come from the file's chapters, or from Community Intro Timestamps (TheIntroDB and IntroDB) when a file has none. A wrong time can be marked from the player."},{"t": "Subtitle sources","p": "The player · technical details","u": "player.html#tech-subtitle-sources","k": "technical Search Online looks on OpenSubtitles, Subdl, Podnapisi and your Jellyfin server at once, best match for the release first. OpenSubtitles and Subdl need a free API key in Settings › Subtitles (make one at opensubtitles.com, under Profile › API consumers), where each site can also be turned off. Signing in to OpenSubtitles raises its daily limit. Subtitle files inside torrents are listed under their language, tagged Torrent. ⇧← and ⇧→ go to the previous or next line."},{"t": "Subtitles that keep their own look","p": "The player · technical details","u": "player.html#tech-subtitles-that-keep-their-own-look","k": "technical Bluebox draws subtitle files and plain text tracks inside MKV and WebM itself, so they follow your style everywhere, including picture in picture and AirPlay. Styled ASS subtitles (signs, karaoke) and picture subtitles from Blu-rays and DVDs are still drawn by VLC, in their own style, and can't be restyled or moved off the picture: pick a plain track in the same language (often labelled SRT), or one from Search Online. Atkinson Hyperlegible and Inter are included; saved presets sync with your profile. With a letterboxed picture you can drop subtitles into the black bar (Move Up for Player Cont"},{"t": "Drift, frame rates and default delay","p": "The player · technical details","u": "player.html#tech-drift-frame-rates-and-default-delay","k": "technical Sync to the Audio listens to the speech on your device and sets the delay and drift. It asks for speech recognition the first time, and keeps working if you close the card. Tap a second line a few minutes later to also fix subtitles that drift. Nudge the delay with { and } (0.1 s), or convert between frame rates (23.976, 24, 25, 29.97, 30 fps). These tools work on subtitle files; tracks inside the video always follow the video. Default Delay in Settings › Subtitles applies to every file."},{"t": "Audio delay and the equaliser","p": "The player · technical details","u": "player.html#tech-audio-delay-and-the-equaliser","k": "technical Audio delay is on the same dial as subtitle timing, for sound ahead of or behind the picture. Dialogue Boost and Night Mode are also in Settings › Playback. The equaliser has Voice, Bass Boost, Treble, Cinema, Music and Headphones presets and a Preamp; it's your profile's and syncs. HLS streams play without it."},{"t": "Tools in detail","p": "The player · technical details","u": "player.html#tech-tools-in-detail","k": "technical Crop to a ratio (16:9, 1.85, 2.35, 2.39, 4:3, 21:9 and more) or by each edge; fit, fill or stretch; pan when zoomed. Starting colour values for every video are in Settings › Picture; they don't apply to HLS streams. The sleep timer stops after a time or at the end of the video. Save Frame saves to Photos on iPhone and iPad, and to Pictures › Bluebox on the Mac."},{"t": "The two video engines","p": "The player · technical details","u": "player.html#tech-the-two-video-engines","k": "technical Bluebox has two engines and picks one for each video. The system player (AVPlayer) plays MP4, M4V, MOV and HLS, and gives picture in picture, AirPlay and power-efficient decoding. VLC (libVLC) plays MKV, AVI, WebM, TS and most other files, including most torrents, with nearly any codec and embedded subtitle tracks. A video playing in VLC can't be sent over AirPlay, and Bluebox doesn't convert it on the fly."},{"t": "Choosing the engine","p": "The player · technical details","u": "player.html#tech-choosing-the-engine","k": "technical Settings › Playback › Player: Automatic (the default: the system player when it can open the file, VLC for the rest), Prefer VLC, or AVPlayer Only (MKV, AVI and WebM won't play). The release picker only picks releases this device can play, and shows each release's file type."},{"t": "How it works","p": "The player · technical details","u": "player.html#tech-how-it-works","k": "technical Only installed players are listed. Torrent streams (and, on iPhone, downloaded files) are served to the other app by Bluebox, which keeps running in the background while it does. The other app doesn't tell Bluebox how far you got, so progress isn't recorded."},{"t": "Every player shortcut","p": "The player · technical details","u": "player.html#shortcuts-player","k": "technical KeyAction SpacePlay or pause ← →Back or forward (10 s by default) ⇧← ⇧→Previous subtitle line (replays the one just said) or next line 0–9Jump to 0–90% of the video [ ]Slower or faster (0.05×) { }Subtitles earlier or later (0.1 s) − =Subtitle size VNext subtitle track CSubtitles off, or back on to the last track BNext audio track < > or , .Step one frame back or forward A / ⇧C / Z / RCycle aspect ratio / crop / zoom; rotate LSet A–B repeat SSave frame N / PNext or previous chapter TShow or hide Tools FFull screen ReturnSkip intro or recap when offered EscClose an open card, then leave full scr"},{"t": "Shortcuts around the app","p": "The player · technical details","u": "player.html#shortcuts-app","k": "technical KeyAction ⌘1–⌘6Home, TV Shows, Movies, New & Hot, My List, Downloads ⌘FSearch ⌘[Back ⌘LAdd to or remove from My List (on a title page) ⌘RRefresh ⌘OOpen files ⇧⌘JJoin a Party… ⌘0Bring back the main window"},{"t": "Privacy & security","p": "Page","u": "privacy.html","k": "privacy security analytics tracking"},{"t": "Nothing is collected","p": "Privacy & security","u": "privacy.html#nothing-collected","k": "analytics tracking crash reports"},{"t": "Who Bluebox talks to","p": "Privacy & security","u": "privacy.html#who-bluebox-talks-to","k": "network services third party"},{"t": "Torrents and your IP address","p": "Privacy & security","u": "privacy.html#torrents-ip","k": "ip address vpn peers upload"},{"t": "Keys and passwords","p": "Privacy & security","u": "privacy.html#keys","k": "keychain api keys passwords tokens"},{"t": "Feature switches","p": "Privacy & security","u": "privacy.html#feature-switches","k": "privacy features spoiler guard statistics search history"},{"t": "Account safety","p": "Privacy & security","u": "privacy.html#account-security","k": "account safety row level security sign up"},{"t": "Mac updates","p": "Privacy & security","u": "privacy.html#updates-security","k": "updater certificate checksum"},{"t": "Report a security problem","p": "Privacy & security","u": "privacy.html#report-vulnerability","k": "vulnerability security report"},{"t": "Your responsibility","p": "Privacy & security","u": "privacy.html#responsibility","k": "legal rights"},{"t": "The stream server","p": "Privacy & security · technical details","u": "privacy.html#tech-the-stream-server","k": "technical Bluebox uploads to other peers while you watch, unless you turn that off. Bluebox's stream server only listens on your own device."},{"t": "Keys in detail","p": "Privacy & security · technical details","u": "privacy.html#tech-keys-in-detail","k": "technical API keys, debrid keys, server tokens, the links of add-ons added by link, and your sign-in are kept in one Bluebox Keychain item. For media servers and Plex, Bluebox signs in once and keeps only the access token, not your password. WebDAV needs the password itself, which is kept in the Keychain. Sync API Keys (off by default) warns that Supabase stores keys as plain text. Remove Keys from Server deletes them again. The debrid key goes to Torrentio, and to StremThru and Comet only with Share Key with Community Add-ons on. Exported logs leave out tokens and keys."},{"t": "Every switch","p": "Privacy & security · technical details","u": "privacy.html#tech-every-switch","k": "technical Statistics (hours watched, Year in Bluebox) and Rows Based on Your Taste are worked out on the device. Spoiler Guard blurs pictures and hides synopses of episodes you haven't seen. Release Alerts asks your add-ons, every 12 hours at most, about films on My List that had nothing to play. Save Search History and Clear Search History. Allow Remote Control of This Device (off by default) and Use This Device as a Remote. These stay on each device: another device can't change what this one allows."},{"t": "How accounts are kept apart","p": "Privacy & security · technical details","u": "privacy.html#tech-how-accounts-are-kept-apart","k": "technical Automatic setup turns off sign-ups on your project once your account exists, so no one else can make an account with the public key in a connect link. Row level security on every table keeps each account to its own rows, and the remote and sync signal use private channels only your account can join. Turn off public Realtime to close the last gap."},{"t": "Certificate and checksum","p": "Privacy & security · technical details","u": "privacy.html#tech-certificate-and-checksum","k": "technical The updater installs only a Bluebox signed with the Bluebox Open Source certificate (SHA-1 8DA48EE5DF68786C0B40A9D6689453892A1F75D0), checks the download against GitHub's checksum, and puts the old version back if the new one fails its check. You can check a download yourself."},{"t": "What to include","p": "Privacy & security · technical details","u": "privacy.html#tech-what-to-include","k": "technical The Bluebox version (Settings › About) and platform, what an attacker needs, and steps to reproduce. You should hear back within a week. Only the latest release gets security fixes. Details are in SECURITY.md."},{"t": "Profiles & Kids","p": "Page","u": "profiles.html","k": "profiles kids children parental controls pin"},{"t": "Profiles","p": "Profiles & Kids","u": "profiles.html#profiles","k": "add switch edit remove profile"},{"t": "Age limits","p": "Profiles & Kids","u": "profiles.html#maturity","k": "age rating limit"},{"t": "Kids profiles","p": "Profiles & Kids","u": "profiles.html#kids","k": "kids profile children family"},{"t": "PIN locks","p": "Profiles & Kids","u": "profiles.html#pin","k": "pin lock settings lock"},{"t": "Forgot a PIN","p": "Profiles & Kids","u": "profiles.html#forgot-pin","k": "forgot pin reset"},{"t": "What's whose, and removing a profile","p": "Profiles & Kids · technical details","u": "profiles.html#tech-what-s-whose-and-removing-a-profile","k": "technical Each profile has its own My List, watch progress and Continue Watching, languages, subtitle style, equaliser, Autoplay Next Episode, statistics and Spoiler Guard. On the Mac, the Profiles menu switches too. Removing a profile (Settings › Profiles, then the profile) deletes its My List and progress from all your devices. When you're signed in, profiles and their libraries sync to your other devices. Trakt follows the first profile."},{"t": "Unrated titles","p": "Profiles & Kids · technical details","u": "profiles.html#tech-unrated-titles","k": "technical Ratings come from TMDB. Allow Unrated Titles decides whether titles with no rating play on a limited profile: on by default for an adult's limit, off for Kids profiles."},{"t": "How locks work","p": "Profiles & Kids · technical details","u": "profiles.html#tech-how-locks-work","k": "technical Settings is locked while a restricted profile is watching: it asks for a PIN if the profile has its own lock, or, for a Kids profile, if any grown-up profile has one. Editing your own restricted profile also asks for the PIN, so a limit can't be lifted from inside it. Only a salted hash of the PIN is kept, in the Keychain. If the Keychain can't be read, the profile counts as locked."},{"t": "iPhone remote","p": "Page","u": "remote.html","k": "remote control touch pad play on"},{"t": "Set it up","p": "iPhone remote","u": "remote.html#setup","k": "allow remote control play on open remote"},{"t": "Gestures","p": "iPhone remote","u": "remote.html#gestures","k": "swipe tap pointer scrub"},{"t": "What the remote shows","p": "iPhone remote","u": "remote.html#screen","k": "highlight ring"},{"t": "While something plays","p": "iPhone remote","u": "remote.html#playing","k": "skip intro next episode tracks close player"},{"t": "If it won't connect","p": "iPhone remote","u": "remote.html#remote-troubleshooting","k": "no mac to control not connecting"},{"t": "Switches and older projects","p": "iPhone remote · technical details","u": "remote.html#tech-switches-and-older-projects","k": "technical Allow Remote Control is off by default, and only the Mac itself can turn it on. Use This Device as a Remote on the iPhone is on by default. A title you open on the iPhone opens on the Mac too. Set up your Supabase project yourself before version 1.0.15? Run setup again (or Check Setup) so it adds the private channel policies the remote needs, then turn off Realtime › Settings › Allow public access in the Supabase dashboard. See Turn off public Realtime."},{"t": "Every gesture","p": "iPhone remote · technical details","u": "remote.html#tech-every-gesture","k": "technical GestureBrowsingWhile something plays SwipeMove the highlight. A fast swipe jumps several items; at the end of what's showing, the page scrolls on.Left or right skips 10 seconds TapPress what's highlightedPlay or pause Hold at the edgeKeep moving— Touch and holdOpen the item's menu, on both screens— Two-finger swipeScroll the page, with a coast— Two-finger tapTurn on the pointer— Swipe in from the left edgeBack— Circle round the pad's edge—Scrub in fine steps The pointer (two-finger tap, or Use a Pointer) clicks anything on the Mac, and comes on by itself on a screen with nothing to highlight. "},{"t": "How the highlight behaves","p": "iPhone remote · technical details","u": "remote.html#tech-how-the-highlight-behaves","k": "technical There's always a highlight. After a while it dims to an outline instead of disappearing, and each new page starts on its first item, so every swipe moves and every tap presses something. Everything you could click on the Mac can be reached: the sidebar, TV Shows and Movies, More Info and My List, See All, the search field, Downloads, every Settings row and switch, and the buttons in sheets. On iPhone the remote opens full screen, so swiping down on the touch pad doesn't close it; the chevron at the top does."},{"t": "“Remote control and instant sync are off”","p": "iPhone remote · technical details","u": "remote.html#tech-remote-control-and-instant-sync-are-off","k": "technical That message in Account & Sync means your project is missing the private channel policies. Run Check Setup, or set up again with an access token, or run migrations/20261030000000_realtime_private.sql in the SQL editor. The remote reconnects on its own when the iPhone opens Bluebox again; commands are confirmed by the Mac and sent again if one is lost."},{"t": "Sources","p": "Page","u": "sources.html","k": "sources addons debrid jellyfin plex"},{"t": "Start here","p": "Sources","u": "sources.html#start","k": "first source getting started"},{"t": "How Play picks what to play","p": "Sources","u": "sources.html#how-play-picks","k": "stream release choose"},{"t": "Add-ons","p": "Sources","u": "sources.html#addons","k": "stremio torrentio stremthru comet manifest"},{"t": "Debrid services","p": "Sources","u": "sources.html#debrid","k": "real-debrid premiumize alldebrid torbox debrid-link api key cached"},{"t": "If it shows an error","p": "Sources","u": "sources.html#debrid-trouble","k": "error key not accepted plan expired limit"},{"t": "Torrents","p": "Sources","u": "sources.html#torrents","k": "peer to peer libtorrent upload seeding vpn"},{"t": "Your own torrents","p": "Sources","u": "sources.html#your-torrents","k": "magnet torrent file"},{"t": "Jellyfin, Emby and Plex","p": "Sources","u": "sources.html#media-servers","k": "jellyfin emby plex server"},{"t": "Jellyfin or Emby","p": "Sources","u": "sources.html#jellyfin","k": ""},{"t": "Plex","p": "Sources","u": "sources.html#plex","k": ""},{"t": "WebDAV folders","p": "Sources","u": "sources.html#webdav","k": "nas nextcloud"},{"t": "SMB (Windows) shares","p": "Sources","u": "sources.html#smb","k": "windows share samba nas"},{"t": "Files and folders","p": "Sources","u": "sources.html#local-files","k": "folder files open mkv mp4 subtitles fix match"},{"t": "Direct links","p": "Sources","u": "sources.html#direct-links","k": "url hls m3u8"},{"t": "Open Movies","p": "Sources","u": "sources.html#open-movies","k": "creative commons blender"},{"t": "Downloads","p": "Sources","u": "sources.html#downloads","k": "offline download season"},{"t": "Smart Downloads","p": "Sources","u": "sources.html#smart-downloads","k": "keep next episodes delete after watching"},{"t": "On iPhone and iPad","p": "Sources","u": "sources.html#downloads-ios","k": "wifi mobile data background battery"},{"t": "Catalog, ratings and Trakt","p": "Sources","u": "sources.html#catalog","k": "tmdb cinemeta omdb trakt ratings"},{"t": "How releases are ranked","p": "Sources · technical details","u": "sources.html#tech-how-releases-are-ranked","k": "technical Bluebox asks each add-on for releases, then picks cached debrid links first (they start at once), then the healthiest release at your preferred resolution that this device can play. A torrent nobody is sharing falls through to the next release by itself. Releases shows every release with its quality, size, seeders and file type. For a show, Bluebox remembers the release group and resolution you last played and prefers them for the next episode (Settings › Torrents & Debrid › Same Group Next Episode)."},{"t": "Add-on links and keys","p": "Sources · technical details","u": "sources.html#tech-add-on-links-and-keys","k": "technical Bluebox speaks the Stremio add-on protocol. An add-on's link is its manifest URL, ending in manifest.json. An add-on added by link often has your debrid key in it, so its link is kept in the Keychain. Torrentio and StremThru are on by default; Comet returns debrid links only."},{"t": "Release settings","p": "Sources · technical details","u": "sources.html#release-settings","k": "technical Preferred Resolution (1080p by default), Sort By (seeders by default) and Hidden Qualities (CAM rips and screeners are hidden by default and never picked). Find Releases Early starts looking as soon as a movie's page opens, so Play starts sooner. Add-on Timeout (in Advanced) is how long Bluebox waits for a slow add-on before going on without it."},{"t": "Where your debrid key goes","p": "Sources · technical details","u": "sources.html#tech-where-your-debrid-key-goes","k": "technical The key stays in this device's Keychain. It goes to Torrentio, and to StremThru and Comet only with Share Key with Community Add-ons on (turn that on if you use them and nothing shows as Cached). It syncs to your other devices only if you turn on Sync API Keys (What syncs)."},{"t": "How torrents stream","p": "Sources · technical details","u": "sources.html#tech-how-torrents-stream","k": "technical Torrents stream peer to peer with libtorrent. Bluebox tries the best few torrents at once, buffers about a minute of the video, then plays while it downloads the rest in order. Torrents Tried at Once and Maximum Peers are in the same section. Extra Trackers (Advanced) adds trackers to every torrent, which can help a quiet one find peers. Bluebox finds peers through HTTP and UDP trackers and web seeds. It has no DHT, so a magnet link with no trackers can't start."},{"t": "Addresses, sign-in and matching","p": "Sources · technical details","u": "sources.html#tech-addresses-sign-in-and-matching","k": "technical An address looks like https://media.example.com or http://192.168.1.20:8096. Bluebox signs in once and keeps only the server's access token, in the Keychain. Films and episodes are matched by the IDs your server stores, then by name and year. Formats Apple's player can't open are converted by your server. Text subtitles from the server show in the player and in Search Online. Use https:// for any server outside your home network; plain http:// is meant for your own network."},{"t": "Adding a Plex server by address","p": "Sources · technical details","u": "sources.html#tech-adding-a-plex-server-by-address","k": "technical Choose Or Enter the Server and type its address with the port (such as http://192.168.1.20:32400) and your X-Plex-Token. Bluebox keeps only the server's access token."},{"t": "Formats and folders that move","p": "Sources · technical details","u": "sources.html#tech-formats-and-folders-that-move","k": "technical MP4, M4V, MOV, MKV, AVI, WebM, TS, M2TS and MTS files are found. See which player opens which. Bluebox keeps access to a folder across launches. A folder that moves or disappears is kept with an error, so you can point it at the new place instead of losing it."},{"t": "What can be downloaded","p": "Sources · technical details","u": "sources.html#tech-what-can-be-downloaded","k": "technical Debrid links, torrents, direct links, Open Movies, WebDAV and media-server files that are already MP4 or MOV. HLS streams can't be downloaded. Simultaneous Downloads is 2 by default (Settings › Downloads)."},{"t": "Every Smart Downloads setting","p": "Sources · technical details","u": "sources.html#tech-every-smart-downloads-setting","k": "technical In Settings › Downloads: Keep Next Episodes (1 by default), Delete After Watching, Delete Watched Films (after 7 days), Storage Limit, Download Quality, Largest Episode, Download Audio, Download Window (only at certain hours), Follow Watching on Other Devices (needs sync) and Subtitles With Downloads. Each show can have its own rules: Download Rules… in the season's ↓ menu. Changing anything there gives the show its own rules; Reset to Settings goes back."},{"t": "Trakt","p": "Sources · technical details","u": "sources.html#tech-trakt","k": "technical Trakt keeps My List in step with your Trakt watchlist and exchanges watched history both ways; custom lists can sync too (off by default), and it follows the first profile. Trakt needs a Trakt app's Client ID built into Bluebox, which the released builds don't include. To use it, build Bluebox yourself with TRAKT_CLIENT_ID and TRAKT_CLIENT_SECRET in Config/Secrets.xcconfig (from a new app at trakt.tv › Settings › Your API Apps), and Settings › Account & Sync then shows Connect Trakt."},{"t": "Sync & accounts","p": "Page","u": "sync.html","k": "sync account supabase sign in"},{"t": "What sync gives you","p": "Sync & accounts","u": "sync.html#why","k": "why sync benefits"},{"t": "Set it up","p": "Sync & accounts","u": "sync.html#automatic-setup","k": "supabase access token setup automatic"},{"t": "Turn off public Realtime","p": "Sync & accounts","u": "sync.html#public-realtime","k": "realtime public access"},{"t": "Usernames and passwords","p": "Sync & accounts","u": "sync.html#usernames","k": "username password forgot"},{"t": "Add another device","p": "Sync & accounts","u": "sync.html#add-device","k": "qr code connect link another device"},{"t": "What syncs","p": "Sync & accounts","u": "sync.html#what-syncs","k": "what syncs api keys"},{"t": "Signing out and switching accounts","p": "Sync & accounts","u": "sync.html#switching-accounts","k": "sign out switch account"},{"t": "Setting it up by hand","p": "Sync & accounts","u": "sync.html#manual-setup","k": "self-hosted manual url key setup.sql"},{"t": "What setup does","p": "Sync & accounts · technical details","u": "sync.html#tech-what-setup-does","k": "technical Setup creates a project named Bluebox in a region near you (or reuses one with that name), adds Bluebox's tables with row level security, turns off confirmation emails, and turns off sign-ups once your account exists. Every step is safe to repeat, so if anything stops it, Try Again carries on where it was. The token is only kept in memory while setup runs, and only ever sent to api.supabase.com. You can delete it on the Access Tokens page (supabase.com/dashboard/account/tokens) afterwards. Free plan already has two projects? Bluebox lists them so you can use one instead (it adds its tables the"},{"t": "Why","p": "Sync & accounts · technical details","u": "sync.html#tech-why","k": "technical Bluebox only uses private channels that just your account can join. With public access on, another client could join a public channel of the same name."},{"t": "Why usernames look like email addresses in Supabase","p": "Sync & accounts · technical details","u": "sync.html#tech-why-usernames-look-like-email-addresses-in-supabase","k": "technical Supabase needs an email address, so Bluebox stores a username as username@bluebox.invalid, an address that can never receive mail. Usernames aren't case-sensitive."},{"t": "What's in the link","p": "Sync & accounts · technical details","u": "sync.html#tech-what-s-in-the-link","k": "technical The bluebox://connect?… link holds only the project's address and its public key, never a token or password. A link opened from outside asks Connect to <server>? first. A device signed in to a different server isn't switched: sign out and choose Change Server… first."},{"t": "Sync in detail","p": "Sync & accounts · technical details","u": "sync.html#tech-sync-in-detail","k": "technical Sync runs at launch, when the app comes to the front, a couple of seconds after you change My List, when you close the player, and from Sync Now. For settings, the newest change wins. An add-on added by link syncs by name only: its link, which can hold a debrid key, stays in the Keychain, and another device shows Paste Link next to it. Sync API Keys syncs the TMDB token, OMDb, OpenSubtitles and debrid keys and add-on links. It asks first, because Supabase stores them as plain text, readable by anyone with your project's dashboard. Remove Keys from Server deletes them from the project without t"},{"t": "Switching accounts in detail","p": "Sync & accounts · technical details","u": "sync.html#tech-switching-accounts-in-detail","k": "technical If changes haven't been uploaded when you sign out, Bluebox warns you. Use <account>'s Library removes this device's copy of the old one (it stays in the old account); Add This Device's Library adds it to the new account. A sign-in link can only have come from someone else, so it's refused."},{"t": "Manual setup steps","p": "Sync & accounts · technical details","u": "sync.html#tech-manual-setup-steps","k": "technical Create a project (the free plan is enough) in a region near you. In the dashboard's SQL Editor, paste the contents of Backend/supabase/setup.sql and run it once. For Watch Party, also run migrations/20261031000000_watch_together.sql. Authentication › Sign In / Providers › Email: turn off Confirm email. Then turn off public Realtime. Project Settings › API Keys: copy the Project URL and the publishable key (sb_publishable_…; a legacy anon key also works) into Bluebox and tap Connect. Create an account on the first device; sign in on the others. Never paste a secret or service-role key. Bluebox "},{"t": "Connect errors","p": "Sync & accounts · technical details","u": "sync.html#connect-errors","k": "technical MessageFix Couldn't reach that project: no server has that nameA typo in the Project URL, or the project is paused. Free projects pause after a week without use: restore it in the dashboard. The project rejected that keyCopy the publishable or anon key again. Bluebox's tables are missingRun setup.sql, then Connect again. An older version of Bluebox's tablesRun migrations/20261028000000_profiles.sql, then Connect again. Username sign-in needs Supabase's Email providerAuthentication › Sign In / Providers › Email › on. New accounts on this server must confirm an emailTurn off Confirm email. Remot"},{"t": "Watch Party","p": "Page","u": "watch-party.html","k": "watch together party friends invite"},{"t": "How it works","p": "Watch Party","u": "watch-party.html#how-it-works","k": "own copy in step"},{"t": "What the host needs","p": "Watch Party","u": "watch-party.html#host-setup","k": "anonymous sign-ins supabase guests"},{"t": "Start a party","p": "Watch Party","u": "watch-party.html#start","k": "start a party lobby share invite"},{"t": "Join a party","p": "Watch Party","u": "watch-party.html#join","k": "join invite code link"},{"t": "With a link","p": "Watch Party","u": "watch-party.html#join-link","k": ""},{"t": "With a code","p": "Watch Party","u": "watch-party.html#join-code","k": ""},{"t": "On the invitation","p": "Watch Party","u": "watch-party.html#join-invitation","k": ""},{"t": "During the party","p": "Watch Party","u": "watch-party.html#during","k": "chat reactions queue step away catch up"},{"t": "Host tools","p": "Watch Party","u": "watch-party.html#host-tools","k": ""},{"t": "If joining fails","p": "Watch Party","u": "watch-party.html#party-troubleshooting","k": "can't join incomplete guests"},{"t": "Anonymous sign-ins and the party tables","p": "Watch Party · technical details","u": "watch-party.html#tech-anonymous-sign-ins-and-the-party-tables","k": "technical In the Supabase dashboard, open Authentication › Sign In / Providers, turn on Allow anonymous sign-ins, and save. Guests then join without making an account. Without it they see “This Bluebox server doesn't let guests join.” A party runs on the host's own Supabase project (their “Bluebox server”). If you set up your project by hand (with setup.sql), also run Backend/supabase/migrations/20261031000000_watch_together.sql in the SQL editor. Automatic setup adds it every time it runs, so running setup again with an access token works too."},{"t": "What's in the link","p": "Watch Party · technical details","u": "watch-party.html#tech-what-s-in-the-link","k": "technical Share Invite… sends a web link to this site's join page. The server address and key are in the part of the link after the #, which stays in your browser and is never sent to GitHub."}];
